}

using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Media;
using Microsoft.UI;
class Program
{
    static TextBlock display;
    static int count;
    static void Increment(object sender, RoutedEventArgs args)
    {
        count++;
        display.Text = "Count: " + count;
    }
    static void Main()
    {
        Window window = new Window();
        window.Title = "SharpForge · Code-first WinUI";
        StackPanel panel = new StackPanel();
        panel.Spacing = 16;
        panel.Padding = new Thickness(24);
        TextBlock title = new TextBlock();
        title.Text = "A live managed application";
        title.FontSize = 26;
        display = new TextBlock();
        display.Name = "Counter";
        display.Text = "Count: 0";
        display.FontSize = 38;
        display.Foreground = new SolidColorBrush(Colors.DodgerBlue);
        Button button = new Button();
        button.Name = "IncrementButton";
        button.Content = "Increment";
        button.HorizontalAlignment = HorizontalAlignment.Left;
        button.Click += Increment;
        panel.Children.Add(title);
        panel.Children.Add(display);
        panel.Children.Add(button);
        window.Content = panel;
        window.Activate();
    }
}

using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
class Program
{
    static TextBox name;
    static Slider level;
    static ComboBox choice;
    static TextBlock result;
    static ProgressBar progress;
    static void Submit(object sender, RoutedEventArgs args)
    {
        result.Text = "Hello " + name.Text + ", item " + choice.SelectedIndex + ", level " + level.Value;
        progress.Value = level.Value;
    }
    static void Main()
    {
        Window window = new Window();
        window.Title = "Managed form";
        StackPanel form = new StackPanel();
        form.Padding = new Thickness(24);
        form.Spacing = 12;
        name = new TextBox(); name.Name = "Name";
        name.PlaceholderText = "Your name"; name.MaxLength = 80;
        level = new Slider(); level.Name = "Level";
        level.Minimum = 0; level.Maximum = 100; level.Value = 42;
        choice = new ComboBox(); choice.Name = "Choice";
        choice.Items.Add("First"); choice.Items.Add("Second"); choice.Items.Add("Third"); choice.SelectedIndex = 0;
        CheckBox remember = new CheckBox(); remember.Content = "Remember this form";
        ToggleSwitch enabled = new ToggleSwitch(); enabled.Header = "Enable notifications";
        Button submit = new Button(); submit.Content = "Submit"; submit.Click += Submit;
        result = new TextBlock(); result.Name = "Result"; result.Text = "Ready";
        progress = new ProgressBar(); progress.Value = 42;
        Expander details = new Expander(); details.Header = "About this form";
        details.Content = new TextBlock() { Text = "All handlers execute as managed C# in a worker." };
        form.Children.Add(name); form.Children.Add(choice); form.Children.Add(level);
        form.Children.Add(remember); form.Children.Add(enabled); form.Children.Add(submit);
        form.Children.Add(result); form.Children.Add(progress); form.Children.Add(details);
        window.Content = form; window.Activate();
    }
}

using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Media;
using Microsoft.UI.Xaml.Shapes;
using Microsoft.UI;
class Program
{
    static void Main()
    {
        StackPanel panel = new StackPanel(); panel.Spacing = 18; panel.Padding = new Thickness(24);
        panel.Children.Add(new TextBlock() { Text = "One scene · three rendering backends", FontSize = 24 });
        Canvas canvas = new Canvas(); canvas.Height = 180; canvas.Width = 560;
        Rectangle rectangle = new Rectangle(); rectangle.Width = 180; rectangle.Height = 110;
        rectangle.Fill = new SolidColorBrush(Colors.DodgerBlue); Canvas.SetLeft(rectangle, 20); Canvas.SetTop(rectangle, 25);
        Ellipse ellipse = new Ellipse(); ellipse.Width = 130; ellipse.Height = 130;
        ellipse.Fill = new SolidColorBrush(Colors.Orange); Canvas.SetLeft(ellipse, 230); Canvas.SetTop(ellipse, 15);
        Line line = new Line(); line.X1 = 380; line.Y1 = 140; line.X2 = 520; line.Y2 = 25;
        line.Stroke = new SolidColorBrush(Colors.CornflowerBlue); line.StrokeThickness = 5;
        canvas.Children.Add(rectangle); canvas.Children.Add(ellipse); canvas.Children.Add(line);
        SharpForge.UI.DrawingSurface drawing = new SharpForge.UI.DrawingSurface(); drawing.Width = 560; drawing.Height = 100;
        for (int i = 0; i < 8; i++)
            drawing.FillRectangle(i * 65 + 10, 80 - i * 8, 48, i * 8 + 12, Colors.CornflowerBlue);
        panel.Children.Add(canvas); panel.Children.Add(drawing);
        Window window = new Window(); window.Title = "WebGPU with fallbacks"; window.Content = panel; window.Activate();
    }
}

using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using System.Threading.Tasks;
class Program
{
    static Button button;
    static TextBlock status;
    static async void Calculate(object sender, RoutedEventArgs args)
    {
        button.IsEnabled = false;
        status.Text = "Calculating…";
        await Task.Delay(700);
        int answer = 6 * 7;
        status.Text = "Answer: " + answer;
        button.IsEnabled = true;
    }
    static void Main()
    {
        StackPanel panel = new StackPanel(); panel.Spacing = 16; panel.Padding = new Thickness(24);
        status = new TextBlock(); status.Name = "Status"; status.Text = "Ready"; status.FontSize = 26;
        button = new Button(); button.Name = "Calculate"; button.Content = "Calculate";
        button.Click += Calculate;
        panel.Children.Add(status); panel.Children.Add(button);
        Window window = new Window(); window.Title = "Async managed UI"; window.Content = panel; window.Activate();
    }
}
